// class. Test bodies are unchanged; see PaintUITestCase for the shared helpers.
//
// This file itself was later split into three classes (LayerPanelUITests,
// BlendModesAndCompositorUITests, SandwichCompositingUITests) so xcodebuild's
// per-class parallel scheduling can distribute them independently; test bodies
// remain unchanged.
//
// `LayerPanelUITests` was then cut again (2026-08-29) into the three classes below —
// LayerStackUITests, LayerFolderAndMaskMenuUITests, LayerPanelControlsUITests — because at
// 19 tests and 534 s it had become the indivisible class setting the whole suite's floor.
// The three are balanced by *measured* per-test seconds rather than by test count, which is
// why the counts are 5/7/7: `testRepeatedAddDeleteLayersDoesNotCrashOrFreeze` alone is 71 s,
// so the class holding it carries fewer tests. See CLAUDE.md's cost-model section. Test
// bodies are again unchanged — only the class boundaries moved.

import XCTest

/// The stack of rows itself: which layer is active, what adding and deleting do to that, and
/// reordering by press-and-hold. Everything here changes the *shape* of the stack — see
/// `LayerFolderAndMaskMenuUITests` for what a drop resolves to and `LayerPanelControlsUITests` for
/// the panel's own controls.
final class LayerStackUITests: PaintUITestCase {

    /// Regression test: with two layers, activating the bottom (non-topmost) layer and drawing
    /// on the canvas must land the stroke on that layer, not get silently swallowed by the
    /// topmost layer's (inactive but still touch-absorbing) host view.
    func testDrawingOnBottomLayerWhenActiveLandsStrokeOnThatLayer() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let layersButton = app.buttons["toolbar.layersButton"]
        XCTAssertTrue(layersButton.waitForExistence(timeout: 5))
        layersButton.tap()

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app) // Now two layers; the new one (index 1) is topmost and active by default.

        let bottomRow = app.staticTexts["layerPanel.row.0"]
        XCTAssertTrue(bottomRow.waitForExistence(timeout: 5))
        bottomRow.tap() // Activate the bottom layer while the top layer stays topmost on screen.

        layersButton.tap() // Close the panel so it can't cover any part of the canvas.

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let start = canvas.coordinate(withNormalizedOffset: CGVector(dx: 0.3, dy: 0.4))
        let end = start.withOffset(CGVector(dx: 80, dy: 0))
        start.press(forDuration: 0.1, thenDragTo: end)

        layersButton.tap() // Reopen the panel to read back stroke counts.

        // The vector marker rather than `readLayerStrokeCount`: both layers are vector now that it is
        // the default kind, so the stroke is geometry in the cel's display list and the raster tier
        // stays at zero for *both* — which would make the second assertion below pass vacuously.
        // Which layer the stroke lands on is what this test is about, and that is unchanged.
        let bottomStrokes = readVectorMarker(app, layerIndex: 0)?.strokes
        let topStrokes = readVectorMarker(app, layerIndex: 1)?.strokes
        XCTAssertEqual(bottomStrokes, 1, "Drawing while the bottom layer is active should add a stroke to it, but got \(String(describing: bottomStrokes))")
        XCTAssertEqual(topStrokes, 0, "The inactive top layer should not receive the stroke, but got \(String(describing: topStrokes))")
    }

    /// Regression test for the layer-deletion bug: deleting a layer *below* the currently active
    /// one must not silently reassign "active" to a different layer. Reproduces the scenario by
    /// activating the middle of three layers, deleting the bottom one, and confirming — via the
    /// checkmark badge LayerRow shows on the active row — that the layer which was active before
    /// the deletion (now shifted down to index 0) is still the one marked active, and that the
    /// layer panel and the animation timeline agree on which one that is.
    func testDeletingLayerBelowActiveKeepsSameLayerActive() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let layersButton = app.buttons["toolbar.layersButton"]
        XCTAssertTrue(layersButton.waitForExistence(timeout: 5))
        layersButton.tap()

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app) // layers: [0, 1], current = 1
        addVectorLayerFromOpenPanel(app) // layers: [0, 1, 2], current = 2

        let middleRow = app.staticTexts["layerPanel.row.1"]
        XCTAssertTrue(middleRow.waitForExistence(timeout: 5))
        middleRow.tap() // Activate layer 1 (the one we expect to remain active after deleting layer 0).
        XCTAssertTrue(app.images["layerPanel.row.1.current"].waitForExistence(timeout: 5), "Layer 1 should be marked active after tapping it")

        swipeDeleteLayerRow(app, layerIndex: 0) // layers shift: old-1 -> 0, old-2 -> 1

        XCTAssertTrue(app.images["layerPanel.row.0.current"].waitForExistence(timeout: 5), "The layer that was active before the deletion (old index 1) should still be marked active, now at index 0")
        XCTAssertFalse(app.images["layerPanel.row.1.current"].exists, "Active status should not have silently moved to the other surviving layer")

        // The animation timeline reads the same canvasManager.layers/currentLayerIndex; confirm
        // it agrees with the panel on layer count and identity after the deletion.
        let timelineName0 = app.staticTexts["timeline.layerName.0"]
        let timelineName1 = app.staticTexts["timeline.layerName.1"]
        XCTAssertTrue(timelineName0.waitForExistence(timeout: 5))
        XCTAssertTrue(timelineName1.waitForExistence(timeout: 5))
    }

    /// Smoke test: repeatedly add and delete layers, and drag a surviving row's opacity slider
    /// right after a deletion. Guards against index-out-of-range crashes/freezes in LayerRow,
    /// whose controls index back into canvasManager.layers by a captured Int — a value that can
    /// go stale for a row mid-removal during the List's own delete animation.
    func testRepeatedAddDeleteLayersDoesNotCrashOrFreeze() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let layersButton = app.buttons["toolbar.layersButton"]
        XCTAssertTrue(layersButton.waitForExistence(timeout: 5))
        layersButton.tap()

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        for _ in 0..<4 {
            addVectorLayerFromOpenPanel(app)
        }
        // layers: [0,1,2,3,4], current = 4

        swipeDeleteLayerRow(app, layerIndex: 4)
        swipeDeleteLayerRow(app, layerIndex: 0)
        swipeDeleteLayerRow(app, layerIndex: 1)

        // The app must still be responsive: both the panel and the timeline must agree there
        // are exactly 2 layers left (indices 0 and 1), and interaction must still work.
        XCTAssertEqual(app.state, .runningForeground, "App should still be running, not crashed")
        XCTAssertTrue(app.staticTexts["layerPanel.row.0"].waitForExistence(timeout: 5))
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.staticTexts["layerPanel.row.2"].exists, "Only 2 layers should remain in the panel")
        XCTAssertTrue(app.staticTexts["timeline.layerName.0"].waitForExistence(timeout: 5))
        XCTAssertTrue(app.staticTexts["timeline.layerName.1"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.staticTexts["timeline.layerName.2"].exists, "Only 2 layers should remain in the timeline, staying in sync with the panel")
    }

    /// Reordering must work by press-and-hold + drag alone, with no Edit mode to enter, and the row
    /// must stay where it was dropped rather than snapping back to its old slot.
    func testLongPressDragReordersLayersAndDropSticks() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        XCTAssertFalse(app.buttons["layerPanel.editButton"].exists, "Reordering should need no Edit button")

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app)
        addVectorLayerFromOpenPanel(app)
        // layers bottom-to-top: [Vector 1, Vector 2, Vector 3]; displayed top-to-bottom: 3, 2, 1.
        // Vector is the default kind, so both the canvas's first layer and the `+` produce
        // `addVectorLayer`'s "Vector N" naming.

        XCTAssertEqual(app.staticTexts["layerPanel.row.2"].label, "Vector 3")
        XCTAssertEqual(app.staticTexts["layerPanel.row.0"].label, "Vector 1")

        // Drag the topmost row below the bottom one so it becomes the bottom of the stack.
        dragRow(layerCell(app, layerIndex: 2), onto: layerCell(app, layerIndex: 0), dropDY: 0.95)

        XCTAssertEqual(app.staticTexts["layerPanel.row.0"].label, "Vector 3",
                       "The dragged layer should stay where it was dropped, not revert to its old index")
        XCTAssertEqual(app.staticTexts["layerPanel.row.2"].label, "Vector 2",
                       "The layers it was dragged past should have shifted up by one")
    }

    /// Swiping a layer row reveals Delete and Duplicate — and no Edit, which moved to the options
    /// menu.
    func testSwipeRevealsDeleteAndDuplicateButNotEdit() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        revealSwipeActions(app, layerIndex: 0)
        XCTAssertTrue(app.buttons["Delete"].waitForExistence(timeout: 5))
        let duplicate = app.buttons["Duplicate"]
        XCTAssertTrue(duplicate.exists, "Swipe actions should offer Duplicate")
        XCTAssertFalse(app.buttons["layerPanel.row.0.edit"].exists, "Edit should no longer be a swipe action")

        duplicate.tap()
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5),
                      "Duplicating should add a second layer")
        XCTAssertEqual(app.staticTexts["layerPanel.row.1"].label, "Vector 1 copy")
    }
}

/// Folders — creating them, what a row dropped onto one (or onto a plain layer) resolves to, and
/// how they nest — together with the mask tuning menu, which is here because §6.2 puts `alphaMask` on
/// `LayerFolder` as well as `Layer`: the menu opens from a folder's options exactly as from a layer's,
/// and the panel-reuse case it must not leak across is a folder's too.
final class LayerFolderAndMaskMenuUITests: PaintUITestCase {

    /// A freshly added folder must be visible right away — before any layer has been put in it —
    /// in both the layer panel and the animation timeline's name column.
    func testAddingFolderShowsItInLayerPanelAndTimeline() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)

        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5),
                      "A folder should appear in the layer panel as soon as it's created, with no layers in it")
        XCTAssertTrue(app.staticTexts["timeline.folderName.Folder 1"].waitForExistence(timeout: 5),
                      "The same folder should appear as a row in the animation timeline")
    }

    /// Dropping one layer squarely onto another **reorders it and creates nothing** — the inverse of
    /// what this test used to assert, and the owner's decision.
    ///
    /// Auto-grouping was a folder the artist never asked for, produced by a gesture they meant as a
    /// reorder: the drag that overshot by half a row wrapped two layers in a "Folder 1" that then had
    /// to be found, opened and dissolved. A destructive combine is still reachable — the two-finger
    /// pinch, which flattens the pair with `CanvasManager.mergeLayers` rather than grouping them — and
    /// that is the deliberate split: the destructive-to-the-tree operation now needs a gesture nobody
    /// performs by accident, and the one people perform constantly does the harmless thing.
    ///
    /// **`dropDY: 0.5` is load-bearing here, and is why the assertion is about the folder rather than
    /// only about the order.** A plain layer row no longer has an "onto" band at all: `dropOnto` losing
    /// its grouping branch would have left the middle 40% of every row resolving to a destination the
    /// drop then reinterpreted as "above", so the row was split in half instead and there is no dead
    /// band left. The exact midpoint is the pixel that used to group, so it is the one worth dropping
    /// on; landing at `midY` resolves to the lower half, which puts the dragged layer beneath its
    /// target.
    func testDroppingLayerOntoLayerReordersItAndCreatesNoFolder() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app) // layers: [Vector 1, Vector 2]

        dragRow(layerCell(app, layerIndex: 1), onto: layerCell(app, layerIndex: 0), dropDY: 0.5)

        XCTAssertFalse(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 2),
                       "A layer landing on a layer must not conjure a folder the artist did not ask for")
        XCTAssertEqual(rowFolder(app, layerIndex: 0), "", "Both layers stay at the top level…")
        XCTAssertEqual(rowFolder(app, layerIndex: 1), "", "…in the container they were already in")

        // Both are still here, and the drop was a real move rather than a no-op: `layerPanel.row.N` is
        // indexed by array position (bottom-to-top), so the dragged "Vector 2" passing below "Vector 1"
        // swaps which name each index reports.
        XCTAssertEqual(app.staticTexts["layerPanel.row.0"].label, "Vector 2",
                       "The dragged layer came to rest beneath its target")
        XCTAssertEqual(app.staticTexts["layerPanel.row.1"].label, "Vector 1")
    }

    /// Dropping onto a folder header moves the layer inside it — the interaction that used to be
    /// fiddly enough to feel broken.
    func testDroppingLayerOntoFolderMovesItInside() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app) // layers: [Vector 1, Vector 2]
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))
        XCTAssertEqual(rowFolder(app, layerIndex: 0), "", "Sanity: the layer starts outside the folder")

        dragRow(layerCell(app, layerIndex: 0), onto: folderCell(app, named: "Folder 1"), dropDY: 0.5)

        XCTAssertEqual(rowFolder(app, layerIndex: 1), "Folder 1",
                       "Dropping onto the folder header should put the layer in the folder")
        // Its timeline row should now report a span rather than reading as empty.
        let folderTrack = app.otherElements["timeline.folderTrack.Folder 1"]
        XCTAssertTrue(folderTrack.waitForExistence(timeout: 5))
        XCTAssertNotEqual(folderTrack.value as? String, "empty")
    }

    /// Folders nest: dropping one folder onto another puts it inside, and the contained rows
    /// indent a level deeper.
    func testDroppingFolderOntoFolderNestsIt() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addFolderFromAddMenu(app) // Folder 1
        addFolderFromAddMenu(app) // Folder 2
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 2"].waitForExistence(timeout: 5))
        XCTAssertEqual(app.staticTexts["layerPanel.folder.Folder 2"].value as? String, "0",
                       "Sanity: both folders start at the top level")

        dragRow(folderCell(app, named: "Folder 2"), onto: folderCell(app, named: "Folder 1"), dropDY: 0.5)

        XCTAssertEqual(app.staticTexts["layerPanel.folder.Folder 2"].value as? String, "1",
                       "A folder dropped onto another should nest one level inside it")
        XCTAssertEqual(app.staticTexts["layerPanel.folder.Folder 1"].value as? String, "0")
    }

    /// The owner's request: "if you click Mask, it brings up a mask tune menu in place of the edit
    /// menu … also include a back button which exits this menu and goes back to the edit menu."
    ///
    /// The two halves worth pinning are that the mask menu **replaces** the edit rows rather than
    /// growing the panel — the tuning sliders used to sit inline under every options menu, which is
    /// the length this change buys back — and that Back restores them, `layerOptions.maskSummary`
    /// included, since that identifier is what several other tests read the menu's state through.
    func testTappingMaskOpensTheTuningMenuAndBackReturnsToTheEditMenu() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        // A fresh document has one layer and it is already selected, so its first tap opens options.
        let row = app.staticTexts["layerPanel.row.0"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        row.tap()
        XCTAssertTrue(app.buttons["layerOptions.rename"].waitForExistence(timeout: 5),
                      "Sanity: the edit menu opened")
        XCTAssertFalse(app.sliders["maskTuning.threshold"].exists,
                       "The tuning sliders no longer sit inline in the edit menu")

        app.buttons["layerOptions.maskButton"].tap()

        XCTAssertTrue(app.sliders["maskTuning.threshold"].waitForExistence(timeout: 5),
                      "Tapping Mask should bring up the tuning menu")
        XCTAssertTrue(app.sliders["maskTuning.antialiasHalfWidth"].exists)
        XCTAssertTrue(app.buttons["maskTuning.reset"].exists)
        XCTAssertFalse(app.buttons["layerOptions.rename"].exists,
                       "…in place of the edit menu, not stacked under it")
        XCTAssertFalse(app.staticTexts["layerOptions.maskSummary"].exists)

        app.buttons["layerOptions.maskBack"].tap()

        XCTAssertTrue(app.buttons["layerOptions.rename"].waitForExistence(timeout: 5),
                      "Back should return to the edit menu")
        XCTAssertTrue(app.staticTexts["layerOptions.maskSummary"].exists,
                      "…with the summary still where every other test reads it")
        XCTAssertFalse(app.sliders["maskTuning.threshold"].exists)
    }

    /// §6.2 puts `alphaMask` on `LayerFolder` as well as `Layer`, and both panels call the one
    /// `maskRow`/`maskMenu` pair — so the menu has to open from a folder's options too, not only a
    /// layer's. The failure this catches is the obvious one: forking the section into two near-copies
    /// and wiring the button up in only one of them.
    func testTheMaskMenuOpensFromAFoldersOptionsToo() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        XCTAssertTrue(app.switches["layerOptions.passThroughToggle"].waitForExistence(timeout: 5),
                      "Sanity: the folder's edit menu opened")

        app.buttons["layerOptions.maskButton"].tap()
        XCTAssertTrue(app.sliders["maskTuning.threshold"].waitForExistence(timeout: 5),
                      "A folder's Mask row opens the same menu a layer's does")
        XCTAssertFalse(app.switches["layerOptions.passThroughToggle"].exists,
                       "…replacing the folder's edit rows, same as on a layer")

        app.buttons["layerOptions.maskBack"].tap()
        XCTAssertTrue(app.switches["layerOptions.passThroughToggle"].waitForExistence(timeout: 5),
                      "Back returns to the folder's edit menu")
    }

    /// The sub-menu belongs to the node whose row was tapped. Both halves matter and they fail
    /// differently: closing the panel and reopening another row tears the view down, while tapping a
    /// second **folder's** options button hands the *same* panel a new id — SwiftUI reuses the view,
    /// so nothing resets on its own and the state has to be cleared explicitly.
    func testTheMaskMenuDoesNotFollowThePanelToAnotherRow() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app)
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5))

        app.staticTexts["layerPanel.row.1"].tap()   // already selected after the add: opens options
        XCTAssertTrue(app.buttons["layerOptions.maskButton"].waitForExistence(timeout: 5))
        app.buttons["layerOptions.maskButton"].tap()
        XCTAssertTrue(app.sliders["maskTuning.threshold"].waitForExistence(timeout: 5))
        app.buttons["layerOptions.close"].tap()

        app.staticTexts["layerPanel.row.0"].tap()   // select
        app.staticTexts["layerPanel.row.0"].tap()   // open options
        XCTAssertTrue(app.buttons["layerOptions.rename"].waitForExistence(timeout: 5),
                      "Another layer's options open on its edit menu, not on the mask menu")
        XCTAssertFalse(app.sliders["maskTuning.threshold"].exists)

        // The same claim where the panel is reused rather than rebuilt.
        addFolderFromAddMenu(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 2"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        XCTAssertTrue(app.buttons["layerOptions.maskButton"].waitForExistence(timeout: 5))
        app.buttons["layerOptions.maskButton"].tap()
        XCTAssertTrue(app.sliders["maskTuning.threshold"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Folder 2.options"].tap()
        XCTAssertTrue(app.switches["layerOptions.passThroughToggle"].waitForExistence(timeout: 5),
                      "Swapping the open panel to another folder lands on its edit menu")
        XCTAssertFalse(app.sliders["maskTuning.threshold"].exists)
    }
}

/// The panel's controls rather than its contents: the views dropdown, the options menu a second tap
/// opens and the fill-reference drop on it, the Mode row that turns a value layer into an effect one,
/// the effect settings bar at the bottom of the window, and the two colour swatches. Nothing here
/// reorders or removes a row; each test drives a control and reads back what it opened.
final class LayerPanelControlsUITests: PaintUITestCase {

    /// The views control is a dropdown, not a cycling button: it lists the saved views, adds new
    /// ones from its own "+", and each saved view swipes left to reveal a delete button.
    func testViewSelectorDropdownAddsSelectsAndDeletesViews() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let viewsButton = app.buttons["layerPanel.viewsButton"]
        XCTAssertTrue(viewsButton.waitForExistence(timeout: 5))
        viewsButton.tap()

        let addView = app.buttons["viewMenu.addButton"]
        XCTAssertTrue(addView.waitForExistence(timeout: 5), "Tapping the views button should open a dropdown with an add button")
        XCTAssertTrue(app.buttons["viewMenu.row.all"].exists, "The dropdown should list the no-view 'All' entry")

        addView.tap()
        let firstView = app.buttons["viewMenu.row.0"]
        XCTAssertTrue(firstView.waitForExistence(timeout: 5), "Adding a view should list it in the dropdown")
        XCTAssertEqual(firstView.value as? String, "1", "The newly added view should be the active one")

        firstView.swipeLeft()
        let deleteButton = app.buttons["Delete"]
        XCTAssertTrue(deleteButton.waitForExistence(timeout: 5), "Views should slide to reveal a delete button, like layer rows do")
        deleteButton.tap()

        XCTAssertTrue(app.buttons["viewMenu.row.0"].waitForNonExistence(timeout: 5), "Deleting a view should remove it from the dropdown")
        XCTAssertEqual(app.buttons["viewMenu.row.all"].value as? String, "1",
                       "Deleting the active view should fall back to 'All'")
    }

    /// Tapping a layer selects it; tapping the selected one again opens its options menu.
    ///
    /// Fill reference used to be a labelled switch inside that menu and is now the row's own drop
    /// button (§6.6), so the toggling half moved here — the claim this keeps that no other test makes
    /// is the **two-tap sequence**: the first tap only selects, and the menu is what the second one
    /// is for.
    func testTappingSelectedLayerOpensOptionsAndTogglesFillReference() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        // A second layer first, so row 0 is *not* the active one. The sequence this pins only exists
        // for a row that isn't already selected: a fresh document has one layer, `currentLayerIndex`
        // is already pointing at it, and so its very first tap opens the menu — correctly. An earlier
        // draft asserted the opposite here and failed on its own false premise rather than on a bug.
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app)
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5),
                      "The added layer becomes row 1 and takes the selection with it")

        let row = app.staticTexts["layerPanel.row.0"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        let summary = app.staticTexts["layerOptions.maskSummary"]
        XCTAssertFalse(summary.exists, "The options menu should not be showing before any tap")

        row.tap() // select
        XCTAssertFalse(summary.exists, "…nor after the first tap on an unselected row, which only selects")
        row.tap() // open options

        XCTAssertTrue(summary.waitForExistence(timeout: 5),
                      "A second tap on the now-selected layer should open its options")

        let fillRef = app.staticTexts["layerPanel.row.0.fillRef"]
        XCTAssertEqual(fillRef.value as? String, "1", "Layers start as fill references")
        let fillRefButton = app.buttons["layerPanel.row.0.fillRefButton"]
        XCTAssertTrue(fillRefButton.waitForExistence(timeout: 5),
                      "The drop button appears on the row for as long as the menu is open")
        fillRefButton.tap()
        XCTAssertEqual(fillRef.value as? String, "0", "Tapping the row's drop should update the row")
    }

    /// §4.4's effect layer, reachable at last: it shipped engine-complete with no way to create one.
    ///
    /// It is reached through the value layer's Mode row now rather than through an add-menu entry of
    /// its own (see `addEffectLayerFromAddMenu`), so this test covers the *whole* route: pick the
    /// kind, pick the mode, and confirm the layer that results is the one §4.4 describes.
    ///
    /// The kind is confirmed the way an artist would notice it — a stroke has nowhere to land, and
    /// `Layer.hasNoDrawingSurface` answers rather than swallowing the touch.
    ///
    /// **The answer is a banner now, not an alert.** The three modal `.alert()`s were replaced by one
    /// transient `CanvasNotice`, so this asserts `canvasNotice` exists rather than
    /// `app.alerts["No Drawing Surface"]`, and it does not dismiss anything afterwards: there is
    /// nothing to dismiss, which is the entire change. Its *value* is the `CanvasNotice.Kind` raw
    /// value rather than the sentence, because the banner deliberately puts the case code there so a
    /// rewording of the message cannot break a test — `CanvasNoticeBanner` says so at the identifier.
    func testTheModePickerCreatesAnEffectLayerAStrokeCannotLandOn() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addEffectLayerFromAddMenu(app)

        let row = app.staticTexts["layerPanel.row.1"]
        XCTAssertTrue(row.waitForExistence(timeout: 5), "The add menu should create a second layer")

        // **The row names the grade.** A value layer that has entered effect mode renames itself to the
        // effect's `displayName` unless the artist has named it by hand (`Layer.hasCustomName`), so the
        // row that read "Value 2" a moment ago now reads this. Asserted here rather than only in the
        // logic tier because the row is the artist's actual view of the change, and this assertion was
        // dropped once already — while the name did *not* follow the effect — which is exactly the
        // window in which the panel could go on lying about a layer with nothing catching it.
        XCTAssertEqual(row.label, "Brightness / Contrast",
                       "The row must say what the layer is, not the flat-colour name it was created with")

        // The Blend Mode row is the panel's own report of which mode the layer is in, and it is the
        // assertion that the pick actually landed rather than merely being tapped. It reports the
        // grade's slug while grading and the blend's raw value otherwise, so this value is also the
        // assertion that the merged row did not leave both answers set.
        XCTAssertEqual(app.buttons["layerOptions.blendModeButton"].value as? String, "brightnesscontrast",
                       "Picking a grade from Blend Mode is what puts a value layer into effect mode")
        XCTAssertFalse(app.buttons["layerOptions.valueColorButton"].exists,
                       "…and the flat colour's swatch goes away with it — the fill is inert in this mode")

        app.buttons["layerOptions.close"].tap()
        openLayerPanel(app)   // close the panel so the canvas is clear
        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let point = safeOutsideCornerPoint(canvas)
        drawLine(on: canvas, from: point, to: CGVector(dx: point.dx + 0.12, dy: point.dy))

        let notice = app.staticTexts["canvasNotice"]
        XCTAssertTrue(notice.waitForExistence(timeout: 5),
                      "The new layer holds no pixels, so the stroke is refused with a transient banner")
        XCTAssertEqual(notice.value as? String, "noDrawingSurface",
                       "The banner names the blocker by `CanvasNotice.Kind`, not by its wording")
    }

    /// The owner's 2026-08-27 ask, as behaviour: *"the effect settings menu right now takes beside
    /// the layers menu. Those two things take up about 80% of the canvas, making it hard to see what
    /// you are editing … the menu is on the bottom, like the same kind of menu that the lasso or move
    /// tool uses."*
    ///
    /// **Three assertions, and the second is the one that would be forgotten.** That the knobs are
    /// *there* is the easy half; that the layer rail has stood down is the half that makes the change
    /// worth anything, because the rail and its options panel are the larger part of what the artist
    /// could not see past. The third is the return trip — the rail comes back, with the same node's
    /// options still open, which is the whole reason `showingEffectSettings` is kept apart from
    /// `layerOptionsID` rather than folded into it.
    ///
    /// **The geometry assertion is deliberately coarse.** "In the bottom half of the window" is what
    /// an XCUITest can honestly say about a layout; the exact 560×300 card is a design decision that
    /// should be free to change without a red test. What must not change silently is which end of the
    /// screen it is at.
    func testEffectSettingsOpenAsABottomBarAndStandTheLayerRailDown() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addEffectLayerFromAddMenu(app)

        let rail = app.tables["layerPanel.list"]
        XCTAssertTrue(rail.waitForExistence(timeout: 5), "Sanity: the rail is up and holding the options panel")

        let openKnobs = app.buttons["layerOptions.effectSettings"]
        XCTAssertTrue(openKnobs.waitForExistence(timeout: 5),
                      "A value layer in effect mode offers the Effect Settings row")
        openKnobs.tap()

        // Brightness / Contrast is what `addEffectLayerFromAddMenu` creates, so these are its knobs.
        let brightness = app.sliders["effectSettings.brightness"]
        XCTAssertTrue(brightness.waitForExistence(timeout: 5), "The row opens the grade's knobs")
        XCTAssertTrue(app.sliders["effectSettings.contrast"].exists)

        XCTAssertFalse(rail.exists, """
            The layer rail is still up behind the effect bar. Moving the 240pt knob panel to the \
            bottom while leaving the ~440pt rail over the artwork does not answer the complaint the \
            change is for — see DrawingView's rail, which stands down while `effectBeingEdited` is \
            non-nil exactly as the Select panel stands down for the Move bar.
            """)
        XCTAssertFalse(openKnobs.exists, "…and the options panel went with it")

        let window = app.windows.element(boundBy: 0).frame
        XCTAssertGreaterThan(brightness.frame.minY, window.midY, """
            The knobs are not in the bottom half of the window, so they are not the "same kind of \
            menu that the lasso or move tool uses" the owner asked for.
            """)

        app.buttons["layerOptions.subMenuBack"].tap()

        XCTAssertTrue(rail.waitForExistence(timeout: 5), "Back brings the rail back…")
        XCTAssertTrue(openKnobs.waitForExistence(timeout: 5),
                      "…with the same node's options still open, rather than at the bare stack")
        XCTAssertFalse(brightness.exists)
    }

    /// The owner's follow-up to the bar above, same day: *"Try to make that menu shorter vertically
    /// because alot of them contain only 1 or 2 sliders which covers like half of it. You already
    /// added the vertical scrolling thing to the bottom bar for things with more, so it should be
    /// good."*
    ///
    /// **This is a regression net, not the acceptance test for that ask, and the distinction is
    /// written into this file's history.** The first attempt at shrink-to-fit (2026-08-27, reverted in
    /// `785f3f7`) *passed this test* against a build whose bar rendered nothing at all: the measured
    /// height collapsed to zero and clipped the rows away, and a clipped view's accessibility frame
    /// does not reflect what painted, so the sliders below went on reporting plausible positions over
    /// an empty card. **A screenshot is the acceptance test.** What is checkable from here is the
    /// arithmetic either side of it — the rows' own content span differs by effect, and the scroll
    /// container the fix resizes is neither zero nor identical between a two-slider effect and a
    /// five-slider one. That second assertion is new with the fix (`EffectSettingsBar.maxRowsHeight`,
    /// `ContentHeightCap`) and is the one that goes red on the specific way it broke last time.
    /// Relative rather than exact-pt, matching the coarse style of the geometry assertion above, so it
    /// survives a padding or font tweak.
    func testEffectSettingsBarIsShorterForFewerSliders() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addEffectLayerFromAddMenu(app)   // Brightness / Contrast: two sliders, the short case.

        let openKnobs = app.buttons["layerOptions.effectSettings"]
        XCTAssertTrue(openKnobs.waitForExistence(timeout: 5))
        openKnobs.tap()

        let header = app.staticTexts["layerOptions.subMenuTitle"]
        XCTAssertTrue(header.waitForExistence(timeout: 5))
        let contrast = app.sliders["effectSettings.contrast"]
        XCTAssertTrue(contrast.waitForExistence(timeout: 5), "Brightness/Contrast's second and last knob")
        let shortSpan = contrast.frame.maxY - header.frame.minY
        XCTAssertGreaterThan(shortSpan, 0)

        // The scrolling rows themselves, found by the knob they contain rather than by index — the
        // timeline has scroll views of its own and they move about. This is the height the fix
        // computes; a zero here is exactly the collapse the reverted attempt shipped.
        let shortScroll = app.scrollViews.containing(.slider, identifier: "effectSettings.contrast").firstMatch
        XCTAssertTrue(shortScroll.exists, "The rows scroll, so there is a scroll view around them")
        let shortRowsHeight = shortScroll.frame.height
        XCTAssertGreaterThan(shortRowsHeight, 0, """
            The effect bar's rows measured zero high. That is not a layout nit — it is the whole card \
            collapsed to its header with the knobs clipped away, which is how the first attempt at \
            this failed while every other assertion in this test still passed.
            """)

        // Back to the rail, flip the same layer to Levels (five sliders, the tall case) through its
        // Blend Mode menu — the same menu `addEffectLayerFromAddMenu` used to pick Brightness/Contrast
        // in the first place — then reopen the settings bar.
        app.buttons["layerOptions.subMenuBack"].tap()
        let modeButton = app.buttons["layerOptions.blendModeButton"]
        XCTAssertTrue(modeButton.waitForExistence(timeout: 5))
        modeButton.tap()
        let levelsItem = app.buttons["layerOptions.blendMode.levels"]
        XCTAssertTrue(levelsItem.waitForExistence(timeout: 5), "The Blend Mode menu lists Levels")
        levelsItem.tap()

        XCTAssertTrue(openKnobs.waitForExistence(timeout: 5))
        openKnobs.tap()

        let header2 = app.staticTexts["layerOptions.subMenuTitle"]
        XCTAssertTrue(header2.waitForExistence(timeout: 5))
        let outputWhite = app.sliders["effectSettings.outputWhite"]
        XCTAssertTrue(outputWhite.waitForExistence(timeout: 5), "Levels opens its five knobs, the last being Output White")
        let tallSpan = outputWhite.frame.maxY - header2.frame.minY

        XCTAssertGreaterThan(tallSpan, shortSpan, """
            Levels' five-slider span should be taller than Brightness/Contrast's two-slider span. A \
            bar that still gave every effect the same fixed card would measure these equal, which is \
            exactly the owner's complaint: "alot of them contain only 1 or 2 sliders which covers like \
            half of it."
            """)

        let tallScroll = app.scrollViews.containing(.slider, identifier: "effectSettings.outputWhite").firstMatch
        XCTAssertTrue(tallScroll.exists)
        XCTAssertGreaterThan(tallScroll.frame.height, shortRowsHeight + 40, """
            The rows are the same height for two sliders as for five, so the card is a fixed cap \
            again rather than a ceiling — see `EffectSettingsBar.maxRowsHeight` and `ContentHeightCap`.
            """)
    }

    /// §4.5's value layer, same story — plus the one control it needs to be worth creating: the
    /// colour it *is*. The swatch carries the hex as its accessibility value (`blendModeRow`'s
    /// convention) so a test can tell a real fill from a control that renders a default.
    func testTheAddMenuCreatesAValueLayerWithAColorControl() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addValueLayerFromAddMenu(app)

        let row = app.staticTexts["layerPanel.row.1"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        XCTAssertEqual(row.label, "Value 2")

        row.tap()   // already selected after the add: opens its options
        let swatch = app.buttons["layerOptions.valueColorButton"]
        XCTAssertTrue(swatch.waitForExistence(timeout: 5),
                      "A value layer's options should offer the colour it is")
        XCTAssertEqual(swatch.value as? String, "808080",
                       "It arrives mid-grey at full alpha (ValueFill.defaultColor)")

        app.buttons["layerOptions.close"].tap()
        app.staticTexts["layerPanel.row.0"].tap()   // select
        app.staticTexts["layerPanel.row.0"].tap()   // open options
        XCTAssertTrue(app.buttons["layerOptions.rename"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.buttons["layerOptions.valueColorButton"].exists,
                       "…and only a value layer's: setLayerFill refuses every other kind anyway")
    }

    /// **One colour picker, not two** (owner, 2026-08-17: "the canvas color changer … is different
    /// than the color changer for the brush. They should be the same").
    ///
    /// The canvas background used to open SwiftUI's stock `ColorPicker` — a grid/spectrum/sliders
    /// sheet with none of the brush panel's hex field or palette library. This asserts by *identity*
    /// rather than by appearance: `colorPanel.svSquare` and `colorPanel.hexField` are
    /// `ColorPickerPanel`'s own identifiers, so their presence inside the Canvas row's popover is
    /// proof that the control behind it is the same object the brush uses, not a lookalike.
    ///
    /// The hex round-trip is the second half and the one that would catch a picker wired to the wrong
    /// binding: typing into the brush's picker must not move the paper, so the value read back is the
    /// canvas swatch's own.
    func testTheCanvasColourRowOpensTheSamePickerTheBrushUses() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let canvasSwatch = app.buttons["layerPanel.canvasColorButton"]
        XCTAssertTrue(canvasSwatch.waitForExistence(timeout: 5),
                      "The layer panel's Canvas row carries the background-colour swatch")
        XCTAssertEqual(canvasSwatch.value as? String, "FFFFFF", "A new project's paper is white")

        canvasSwatch.tap()

        // ColorPickerPanel's own identifiers. The stock ColorPicker has neither.
        XCTAssertTrue(app.otherElements["colorPanel.svSquare"].waitForExistence(timeout: 5),
                      "The canvas colour opens ColorPickerPanel, not a second colour UI")
        XCTAssertTrue(app.buttons["colorPanel.tab.palettes"].exists,
                      "…including its palette library, which the stock picker never had")

        let hexField = app.textFields["colorPanel.hexField"]
        XCTAssertTrue(hexField.exists, "…and its hex field")
        setHexField(app, hexField, to: "336699")

        // Dismiss the popover by tapping the panel behind it, then read the swatch back.
        app.staticTexts["Layers"].tap()
        XCTAssertTrue(canvasSwatch.waitForExistence(timeout: 5))
        XCTAssertEqual(canvasSwatch.value as? String, "336699",
                       "The pick reached canvasBackgroundColor — the row's own binding, not the brush's")
    }
}


final class BlendModesAndCompositorUITests: PaintUITestCase {

    /// **§6.5's picker, at the panel rather than at `CanvasManager`.** Opening a layer's options menu
    /// *is* the mask-edit session, so every other row grows a checkmark and a fill-reference button
    /// while it is open, and both go away when it closes. What this pins that the logic tests cannot
    /// is the wiring: that the two controls appear on rows, target the row they sit on, and are gated
    /// on the menu rather than on a switch inside it — the switch this replaced.
    func testOpeningALayerMenuPutsMaskAndFillControlsOnTheRows() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addVectorLayerFromOpenPanel(app)
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5))

        XCTAssertFalse(app.buttons["layerPanel.row.0.maskSource"].exists,
                       "No menu open, no picker — the rows carry nothing until one is")

        let top = app.staticTexts["layerPanel.row.1"]
        top.tap()   // already selected after the add; this opens its options
        let summary = app.staticTexts["layerOptions.maskSummary"]
        XCTAssertTrue(summary.waitForExistence(timeout: 5), "The layer menu should be open")

        let sourceCheck = app.buttons["layerPanel.row.0.maskSource"]
        XCTAssertTrue(sourceCheck.waitForExistence(timeout: 5), "Every other row is a candidate source")
        XCTAssertEqual(sourceCheck.value as? String, "0")
        let ownCheck = app.buttons["layerPanel.row.1.maskSource"]
        XCTAssertTrue(ownCheck.exists, "The row under edit carries the control…")
        XCTAssertFalse(ownCheck.isEnabled, "…inert, because it is the one row that can never be its own source")

        sourceCheck.tap()
        XCTAssertEqual(sourceCheck.value as? String, "1", "The checkmark is the pick")
        XCTAssertEqual(summary.value as? String, "1", "…and the menu it belongs to reports it")

        let fillRefButton = app.buttons["layerPanel.row.0.fillRefButton"]
        XCTAssertTrue(fillRefButton.exists, "The fill-reference button sits beside the checkmark, same rows")
        XCTAssertEqual(fillRefButton.value as? String, "1", "Layers default to bounding the fill")
        fillRefButton.tap()
        XCTAssertEqual(fillRefButton.value as? String, "0")
        XCTAssertEqual(app.staticTexts["layerPanel.row.0.fillRef"].value as? String, "0",
                       "The row's own subtitle agrees, so the button drove the model and not just itself")

        app.buttons["layerOptions.close"].tap()
        XCTAssertFalse(app.buttons["layerPanel.row.0.maskSource"].waitForExistence(timeout: 2),
                       "Closing the menu closes the session, and the rows go back to being rows")
    }

    /// Merge Down flattens a layer into the one below it, leaving a single layer behind. Same model
    /// call the two-finger pinch gesture makes.
    func testMergeDownFlattensTwoLayersIntoOne() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let point = safeOutsideCornerPoint(canvas)
        drawLine(on: canvas, from: point, to: CGVector(dx: point.dx + 0.12, dy: point.dy))

        openLayerPanel(app)
        let addLayer = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addLayer.waitForExistence(timeout: 5)) // the panel has to finish presenting first
        addVectorLayerFromOpenPanel(app) // layers: [Vector 1 (drawn on), Vector 2]
        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForExistence(timeout: 5))

        let top = app.staticTexts["layerPanel.row.1"]
        top.tap()
        top.tap()
        let mergeDown = app.buttons["layerOptions.mergeDown"]
        XCTAssertTrue(mergeDown.waitForExistence(timeout: 5))
        mergeDown.tap()

        XCTAssertTrue(app.staticTexts["layerPanel.row.1"].waitForNonExistence(timeout: 5),
                      "Merging should leave exactly one layer")
        XCTAssertTrue(app.staticTexts["layerPanel.row.0"].waitForExistence(timeout: 5))
        XCTAssertEqual(readHasBakedImage(app, layerIndex: 0), false,
                       "The surviving layer should hold the flattened pixels in the raster tier, not a separate baked-image tier")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 0), 1,
                       "The flattened pixels of both layers should register as raster content")
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: point.dx + 0.06, dy: point.dy)),
                       "The merged artwork should still be on the canvas")
    }

    /// Merging a vector layer must leave the survivor as a genuine `.raster` layer, not `.vector`
    /// with emptied-out geometry — the inconsistency `rasterizeLayer` exists to prevent.
    func testMergeDownFromVectorLayerRasterizesTheSurvivor() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        app.buttons["toolbar.layersButton"].tap()
        let addButton = app.buttons["layerPanel.addButton"]
        XCTAssertTrue(addButton.waitForExistence(timeout: 5))
        addButton.press(forDuration: 1.2)
        let vectorItem = app.buttons["Vector Layer"]
        XCTAssertTrue(vectorItem.waitForExistence(timeout: 5))
        vectorItem.tap() // layers: [Vector 1, Vector 2 (active)]
        app.buttons["toolbar.layersButton"].tap() // close panel

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        drawLine(on: canvas, from: CGVector(dx: 0.3, dy: 0.5), to: CGVector(dx: 0.7, dy: 0.5))

        app.buttons["toolbar.layersButton"].tap()
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, true, "Setup: should be a vector layer")
        // Raster has to be asked for by name now that the plain `+` makes a vector layer, and a
        // raster layer on top is the whole premise: this test is about what merging one *into* a
        // vector layer leaves behind.
        addButton.press(forDuration: 1.2)
        let rasterItem = app.buttons["Raster Layer"]
        XCTAssertTrue(rasterItem.waitForExistence(timeout: 5), "The add menu should still offer a Raster Layer option")
        rasterItem.tap() // layers: [Vector 1, Vector 2, Layer 3 (active, raster, on top)]
        XCTAssertTrue(app.staticTexts["layerPanel.row.2"].waitForExistence(timeout: 5))

        let top = app.staticTexts["layerPanel.row.2"]
        top.tap()
        top.tap()
        let mergeDown = app.buttons["layerOptions.mergeDown"]
        XCTAssertTrue(mergeDown.waitForExistence(timeout: 5))
        mergeDown.tap() // merges Layer 3 into the vector layer below it

        XCTAssertTrue(app.staticTexts["layerPanel.row.2"].waitForNonExistence(timeout: 5))
        XCTAssertEqual(readVectorMarker(app, layerIndex: 1)?.isVector, false,
                       "The survivor should come out of the merge as a raster layer, not vector with emptied geometry")
        XCTAssertEqual(readHasBakedImage(app, layerIndex: 1), false, "The survivor should hold the flattened pixels in the raster tier, not a separate baked-image tier")
        XCTAssertEqual(readLayerStrokeCount(app, layerIndex: 1), 1, "The flattened pixels should register as raster content")
        app.buttons["toolbar.layersButton"].tap() // close panel

        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: 0.5, dy: 0.5)), "The vector stroke should survive the merge")
    }

    // MARK: - §4.1/§4.2 group properties

    /// The regression phase 4b exists to fix: `toggleFolderVisibility` stopped writing through to
    /// children (§4.1), so the live canvas has to consult `isLayerEffectivelyVisible` per layer
    /// instead of the layer's own flag, or hiding a group does nothing on screen.
    func testHidingFolderHidesContentsOnCanvasAndReshowingRestoresThem() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))

        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))
        let point = safeOutsideCornerPoint(canvas)
        drawLine(on: canvas, from: point, to: CGVector(dx: point.dx + 0.12, dy: point.dy))
        XCTAssertFalse(isWhitish(rgbaPixel(of: canvas, dx: point.dx + 0.06, dy: point.dy)),
                       "Setup: the stroke should be on the canvas")

        openLayerPanel(app)
        addFolderFromAddMenu(app) // Folder 1, empty, at the top
        dragRow(layerCell(app, layerIndex: 0), onto: folderCell(app, named: "Folder 1"), dropDY: 0.5)
        XCTAssertEqual(rowFolder(app, layerIndex: 0), "Folder 1", "Setup: the drawn layer should now be inside the folder")

        app.buttons["layerPanel.folder.Folder 1.visibility"].tap()
        app.buttons["toolbar.layersButton"].tap() // close panel to see the canvas

        XCTAssertTrue(waitUntilBlank(canvas, dx: point.dx + 0.06, dy: point.dy, timeout: 5),
                      "Hiding the folder should hide its contents on the live canvas, not just in the panel")

        app.buttons["toolbar.layersButton"].tap() // reopen
        app.buttons["layerPanel.folder.Folder 1.visibility"].tap() // show again
        app.buttons["toolbar.layersButton"].tap() // close

        XCTAssertTrue(waitUntilFilled(canvas, dx: point.dx + 0.06, dy: point.dy, timeout: 5),
                      "Re-showing the folder should restore its contents")
    }

    /// A folder row's tap already means expand/collapse, so its options — the pass-through toggle
    /// (§4.2) and Rename — live behind the row's own button instead of "tap the already-selected
    /// row again", which is how a layer row opens the same menu.
    func testFolderOptionsButtonOpensPassThroughToggleOffByDefault() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.switches["layerOptions.passThroughToggle"].exists,
                       "The options menu should not be showing before the button is tapped")

        app.buttons["layerPanel.folder.Folder 1.options"].tap()

        let toggle = app.switches["layerOptions.passThroughToggle"]
        XCTAssertTrue(toggle.waitForExistence(timeout: 5), "Tapping the folder's options button should open its menu")
        XCTAssertEqual(toggle.value as? String, "0", "Isolated is the default (§4.2), so Pass Through starts off")

        // Hit the switch itself — tapping a SwiftUI Toggle's label doesn't flip it.
        toggle.coordinate(withNormalizedOffset: CGVector(dx: 0.93, dy: 0.5)).tap()
        XCTAssertEqual(toggle.value as? String, "1", "Toggling should flip the switch")

        // Close and reopen to confirm the flip reached the model (`setFolderIsolated`), not just
        // the switch's own transient state.
        app.buttons["layerOptions.close"].tap()
        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        XCTAssertEqual(app.switches["layerOptions.passThroughToggle"].value as? String, "1",
                       "The toggle should reflect the folder's isIsolated flag, not reset when the panel reopens")
    }

    /// Folder rows get the same opacity slider layer rows already have (§4.1), routed through
    /// `CanvasManager.setFolderOpacity` rather than the raw `layers[i].opacity = value` write the
    /// layer rows use (folders have no such index).
    func testFolderOpacitySliderPersistsThroughSetFolderOpacity() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))

        let slider = app.sliders["layerPanel.folder.Folder 1.opacity"]
        XCTAssertTrue(slider.waitForExistence(timeout: 5), "Folder rows should show the same opacity slider layer rows have")
        XCTAssertEqual(sliderNumericValue(slider), 100, "A fresh folder starts at full opacity")

        slider.adjust(toNormalizedSliderPosition: 0.3)
        let after = sliderNumericValue(slider)
        XCTAssertLessThan(after, 100, "Dragging the slider down should lower the folder's opacity")

        // Collapsing and re-expanding forces a fresh `configure()` from the model, which only
        // shows the dragged value if it reached `setFolderOpacity` rather than staying local to
        // the control (folder rows have no per-layer index for a raw write to land on).
        app.staticTexts["layerPanel.folder.Folder 1"].tap() // collapse
        app.staticTexts["layerPanel.folder.Folder 1"].tap() // expand
        XCTAssertEqual(sliderNumericValue(app.sliders["layerPanel.folder.Folder 1.opacity"]), after, accuracy: 1,
                       "The opacity should persist on the model, not reset when the row is reconfigured")
    }

    // MARK: - §7 blend modes

    /// The picker (`blendModeRow` in LayerPanel.swift) is a `Menu` grouped by `BlendMode.menuGroups`;
    /// picking an item should reach `CanvasManager.setLayerBlendMode` — not stay local to the control
    /// — show on the row without closing the options panel (§7's whole point: a mode has to be
    /// readable without opening options), and survive the panel closing and reopening.
    func testSettingLayerBlendModeShowsOnRowAndPersists() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)

        let row = app.staticTexts["layerPanel.row.0"]
        XCTAssertTrue(row.waitForExistence(timeout: 5))
        row.tap() // select
        row.tap() // open options

        let picker = app.buttons["layerOptions.blendModeButton"]
        XCTAssertTrue(picker.waitForExistence(timeout: 5))
        XCTAssertEqual(picker.value as? String, "normal", "A fresh layer starts at Normal")

        let rowBlendMode = app.otherElements["layerPanel.row.0.blendMode"]
        XCTAssertEqual(rowBlendMode.value as? String, "normal", "Setup: the row's own marker should agree")

        picker.tap()
        let multiply = app.buttons["layerOptions.blendMode.multiply"]
        XCTAssertTrue(multiply.waitForExistence(timeout: 5), "The menu should list Multiply, grouped under darkening (§7)")
        multiply.tap()

        XCTAssertEqual(picker.value as? String, "multiply", "Picking a mode should update the button's own state")
        XCTAssertEqual(rowBlendMode.value as? String, "multiply",
                       "The row should reflect the new mode immediately — LayerRowModel.blendMode is part of its Equatable conformance, so the diffable data source reconfigures the cell")

        // Close and reopen to confirm the pick reached `setLayerBlendMode`, not just local control state.
        app.buttons["layerOptions.close"].tap()
        row.tap()
        row.tap()
        XCTAssertEqual(app.buttons["layerOptions.blendModeButton"].value as? String, "multiply",
                       "The picker should reflect the layer's blendMode, not reset when the panel reopens")
    }

    /// Same contract as the layer picker above, routed through `setFolderBlendMode` instead — the
    /// group side of §7, which is the same picker (`blendModeRow`) reused rather than a second one.
    func testSettingFolderBlendModeShowsOnRowAndPersists() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Folder 1"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        let picker = app.buttons["layerOptions.blendModeButton"]
        XCTAssertTrue(picker.waitForExistence(timeout: 5))
        XCTAssertEqual(picker.value as? String, "normal", "A fresh folder starts at Normal")

        picker.tap()
        let screen = app.buttons["layerOptions.blendMode.screen"]
        XCTAssertTrue(screen.waitForExistence(timeout: 5), "The menu should list Screen, grouped under lightening (§7)")
        screen.tap()

        XCTAssertEqual(picker.value as? String, "screen")
        let rowBlendMode = app.otherElements["layerPanel.folder.Folder 1.blendMode"]
        XCTAssertEqual(rowBlendMode.value as? String, "screen",
                       "The folder row should reflect the new mode the same way a layer row does")

        // Close and reopen to confirm the pick reached `setFolderBlendMode`, not just local control state.
        app.buttons["layerOptions.close"].tap()
        app.buttons["layerPanel.folder.Folder 1.options"].tap()
        XCTAssertEqual(app.buttons["layerOptions.blendModeButton"].value as? String, "screen",
                       "The picker should reflect the folder's blendMode, not reset when the panel reopens")
    }

}

final class SandwichCompositingUITests: PaintUITestCase {

    // MARK: - §5.2's sandwich on the live canvas

    /// Where the two crossed strokes below meet — the one pixel every assertion in this section is
    /// about. Vertically centred, so it is never in the letterbox margin (`visibleCanvasBounds`).
    private var crossing: CGVector { CGVector(dx: 0.45, dy: 0.5) }

    /// Sets the brush colour through the colour panel and closes it again, so it cannot cover the
    /// canvas the next probe screenshots.
    private func setBrushColor(_ app: XCUIApplication, hex: String) {
        let colorButton = app.buttons["toolbar.colorButton"]
        XCTAssertTrue(colorButton.waitForExistence(timeout: 5))
        colorButton.tap()
        let hexField = app.textFields["colorPanel.hexField"]
        XCTAssertTrue(hexField.waitForExistence(timeout: 5))
        setHexField(app, hexField, to: hex)
        colorButton.tap()
    }

    /// Two overlapping strokes on two layers, in colours whose product is nothing like either of
    /// them: cyan underneath, magenta on top. At `crossing` a **Normal** top layer reads magenta
    /// (255, 0, 255) and a **Multiply** one reads blue (0, 0, 255) — the red channel alone is the
    /// whole discriminator, which is what makes this readable through a screenshot's own rounding.
    ///
    /// Both strokes run the same path so the overlap is the width of a stroke rather than the size
    /// of a crossing, and `crossing` is its midpoint — comfortably inside the solid core of both,
    /// away from the antialiased edges.
    private func drawCrossedStrokesOnTwoLayers(_ app: XCUIApplication) -> XCUIElement {
        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        setBrushColor(app, hex: "00FFFF")
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: 0.5), to: CGVector(dx: 0.55, dy: 0.5))

        openLayerPanel(app)
        addVectorLayerFromOpenPanel(app) // layer 1, topmost and active
        app.buttons["toolbar.layersButton"].tap()

        setBrushColor(app, hex: "FF00FF")
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: 0.5), to: CGVector(dx: 0.55, dy: 0.5))
        return canvas
    }

    /// Polls a canvas pixel until `matches` holds. The sandwich composites off the main thread (see
    /// `CanvasView.Coordinator.startSandwichRebuild`), so every assertion about what the canvas shows
    /// after a model change is a wait, exactly as `waitUntilFilled` is for the fill.
    @discardableResult
    private func waitForPixel(_ canvas: XCUIElement, at point: CGVector, timeout: TimeInterval = 10,
                              matches: ((r: UInt8, g: UInt8, b: UInt8, a: UInt8)) -> Bool) -> (r: UInt8, g: UInt8, b: UInt8, a: UInt8)? {
        let deadline = Date().addingTimeInterval(timeout)
        var last: (r: UInt8, g: UInt8, b: UInt8, a: UInt8)?
        while Date() < deadline {
            last = rgbaPixel(of: canvas, dx: Double(point.dx), dy: Double(point.dy))
            if let last, matches(last) { return last }
            Thread.sleep(forTimeInterval: 0.2)
        }
        return last
    }

    /// How many times the canvas has entered §5.2's mid-stroke presentation — the latch
    /// `CanvasView.Coordinator.midStrokeEntryCount` keeps, because the presentation itself only
    /// exists while a touch is down and XCUITest cannot drag and look at once.
    private func midStrokeEntries(_ app: XCUIApplication) -> Int? {
        let label = app.otherElements["canvas.host"].label
        guard let field = label.split(separator: " ").first(where: { $0.hasPrefix("entries:") }) else { return nil }
        return Int(field.dropFirst("entries:".count))
    }

    /// **The regression guard for the mask trick, and the reason `LayerHostView.setBlanked` uses a
    /// mask rather than `isHidden`.**
    ///
    /// While the sandwich is engaged every layer host is blanked, including the active one at rest.
    /// `UIView.hitTest` returns nil for a view that is hidden or below alpha 0.01, so blanking that
    /// way would mean the first touch of a stroke never reaches the stroke view — the artist draws
    /// and *nothing happens*, with no error anywhere. The stroke count is the assertion that catches
    /// it: it can only be non-zero if the touch was delivered.
    func testAStrokeStillLandsWhileTheSandwichIsEngaged() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        setBlendMode(app, layerIndex: 0, to: "multiply")
        XCTAssertEqual(vectorMarkerViaPanel(app, layerIndex: 0)?.strokes, 0, "Setup: nothing drawn yet")
        XCTAssertEqual(sandwichState(app), "rest",
                       "A blending leaf is exactly the document Core Animation cannot draw, so the compositor should have taken over")

        setBrushColor(app, hex: "00FFFF")
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: 0.5), to: CGVector(dx: 0.55, dy: 0.5))

        XCTAssertEqual(vectorMarkerViaPanel(app, layerIndex: 0)?.strokes, 1,
                       "The stroke has to reach the blanked host. A zero here means the host was hidden rather than masked and the touch was never delivered")
        XCTAssertNotNil(waitForPixel(canvas, at: crossing) { !isWhitish($0) },
                        "And it has to be visible: on lift the canvas goes back to `composite(full)`, which contains the stroke")
    }

    /// **"I cannot see my paint strokes live" — the one thing no other case in this file looks at.**
    ///
    /// Every other sandwich assertion samples the canvas *after* lift, where `composite(full)`
    /// contains the stroke and the picture is right whether or not a single pixel of ink was on
    /// screen while the artist was drawing. So a canvas that shows nothing until the pen comes up
    /// passes all of them.
    ///
    /// **Why this reads a latch instead of screenshotting mid-gesture.** The obvious test — drag
    /// slowly on a background queue, probe the pixel from the test thread — does not work and cannot
    /// be made to work: XCUITest synthesises events on the main thread and throws
    /// `"Must be called on the main thread"` from anywhere else, so a test cannot drag and look at
    /// the same time. `midStrokeEntryCount` (`CanvasView.Coordinator`) is the seam that makes the
    /// question answerable after the fact: a stroke drawn while the sandwich is engaged has to have
    /// *entered* the mid-stroke presentation at some point, and a stroke that never did is exactly a
    /// stroke whose ink the artist could not see until lift.
    ///
    /// **The second stroke, not the first, and that is the whole point.** `updateSandwich` is the
    /// only thing that unblanks the active host, and it runs from a SwiftUI pass. The first stroke on
    /// a frame spawns a cel, which publishes, which causes the pass — so the first stroke draws
    /// visibly and hides the defect. The second stroke publishes nothing (a dab must not, §5.2), so
    /// if nothing applies the mid-stroke presentation at touch-down the host stays blanked for the
    /// whole stroke.
    func testEveryStrokeEntersTheMidStrokePresentationNotJustTheFirst() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = app.otherElements["canvas.host"]
        XCTAssertTrue(canvas.waitForExistence(timeout: 5))

        setBlendMode(app, layerIndex: 0, to: "multiply")
        XCTAssertEqual(sandwichState(app), "rest", "Setup: a blending leaf puts the canvas on the compositor")
        XCTAssertEqual(midStrokeEntries(app), 0, "Setup: nothing drawn, so the mid-stroke picture has never been shown")
        setBrushColor(app, hex: "00FFFF")

        // Stroke one spawns the cel, and that spawn publishes — so this stroke gets a SwiftUI pass
        // for free and enters the mid-stroke presentation even with the defect present.
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: 0.5), to: CGVector(dx: 0.55, dy: 0.5))
        XCTAssertNotNil(waitForPixel(canvas, at: crossing) { !isWhitish($0) }, "Setup: the first stroke landed")
        XCTAssertEqual(midStrokeEntries(app), 1, "Setup: the first stroke is the one that gets a pass for free")

        // Let the 400 ms thumbnail-regen debounce land before the stroke under test, so its publish
        // cannot supply the SwiftUI pass whose absence is the whole subject.
        Thread.sleep(forTimeInterval: 1.5)
        XCTAssertEqual(sandwichState(app), "rest", "Setup: settled back to rest, so every host is blanked again")

        // Stroke two, on fresh paper. The cel already exists, so nothing publishes at touch-down.
        let second = CGVector(dx: 0.45, dy: 0.65)
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: second.dy), to: CGVector(dx: 0.55, dy: second.dy))

        XCTContext.runActivity(named: "after the second stroke") { activity in
            activity.add(XCTAttachment(string: "label=\(app.otherElements["canvas.host"].label)"))
        }
        XCTAssertEqual(midStrokeEntries(app), 2,
                       "The second stroke has to show the artist their ink too. A count still at 1 means the mid-stroke picture was never put up for it — the active host stayed blanked by §5.2 for the whole gesture and the stroke only appeared on lift")

        XCTAssertNotNil(waitForPixel(canvas, at: second) { !isWhitish($0) }, "The stroke survives the lift")
        XCTAssertEqual(sandwichState(app), "rest", "…and the canvas goes back to `composite(full)`")
    }

    /// **§11's done-criterion for phase 5b: a Multiply layer looks multiplied on the canvas the
    /// artist is drawing on.** Before the sandwich, `reconcileLayers` handed every layer to Core
    /// Animation as a flat sibling, so the mode showed on the layer row and in the project thumbnail
    /// and changed nothing on canvas.
    ///
    /// Doubles as the "a blend change brings the canvas back in sync" case: the mode is picked with
    /// both strokes already on the canvas, so the pixel has to *move* rather than merely start right.
    func testAMultiplyLayerLooksMultipliedOnTheLiveCanvas() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = drawCrossedStrokesOnTwoLayers(app)

        XCTAssertEqual(sandwichState(app), "off", "Two Normal layers are still Core Animation's own case")
        guard let normal = waitForPixel(canvas, at: crossing, matches: { $0.r > 200 && $0.b > 200 }) else {
            return XCTFail("Setup: the magenta stroke should cover the cyan one at the crossing")
        }
        XCTAssertLessThan(normal.g, 80, "Setup: magenta over cyan, source-over, is magenta")

        setBlendMode(app, layerIndex: 1, to: "multiply")

        XCTAssertEqual(sandwichState(app), "rest")
        guard let multiplied = waitForPixel(canvas, at: crossing, matches: { $0.r < 80 }) else {
            return XCTFail("The canvas never showed the multiply")
        }
        XCTAssertLessThan(multiplied.r, 80,
                          "Magenta multiplied into cyan has no red left — this is the assertion the whole phase exists for, and \(multiplied) is what an unblended flat sibling still looks like")
        XCTAssertGreaterThan(multiplied.b, 200, "Blue survives both, so it is what tells a multiply from a layer that simply vanished")
    }

    /// **The risk containment, stated as a test.** Every document that could exist before phase 5a
    /// has to keep taking today's exact code path — one host per layer, no compositor, no cached
    /// images — and `needsCompositorOnCanvas` is what guarantees it. If this ever reads anything but
    /// "off", every project ever made starts rendering through a path it has never rendered through.
    func testAnAllNormalDocumentNeverEngagesTheSandwich() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = drawCrossedStrokesOnTwoLayers(app)

        XCTAssertEqual(sandwichState(app), "off", "Two Normal layers on a flat stack")
        XCTAssertEqual(vectorMarkerViaPanel(app, layerIndex: 1)?.strokes, 1, "Drawing behaves as before")

        // A folder at its defaults is a transparent parenthesis — opacity 1, normal, isolated over
        // nothing that blends — so nesting must not engage anything either.
        openLayerPanel(app)
        addFolderFromAddMenu(app)
        dragRow(layerCell(app, layerIndex: 1), onto: folderCell(app, named: "Folder 1"), dropDY: 0.5)
        XCTAssertEqual(rowFolder(app, layerIndex: 1), "Folder 1", "Setup: the top layer should now be inside the folder")
        app.buttons["toolbar.layersButton"].tap()

        XCTAssertEqual(sandwichState(app), "off", "An untouched folder changes nothing Core Animation cannot express")
        drawLine(on: canvas, from: CGVector(dx: 0.35, dy: 0.42), to: CGVector(dx: 0.55, dy: 0.42))
        XCTAssertEqual(vectorMarkerViaPanel(app, layerIndex: 1)?.strokes, 2,
                       "And drawing still lands, on the same path it always did")
        XCTAssertEqual(sandwichState(app), "off", "Drawing is not what engages it either")
    }

    /// The invalidation contract from the other side: everything *except* the live stroke has to
    /// move the cached composites. A layer switch re-cuts the tree, a visibility toggle changes what
    /// is in it, and undo changes a layer's pixels — each has to reach the canvas, and each would sit
    /// there showing a stale composite if it were missing from `SandwichKey`.
    func testTheBlendedCanvasComesBackInSyncAfterLayerSwitchVisibilityToggleAndUndo() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = drawCrossedStrokesOnTwoLayers(app)
        setBlendMode(app, layerIndex: 1, to: "multiply")
        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.r < 80 }), "Setup: multiplied")

        // A layer switch changes only where the tree is cut, so the picture must not change with it.
        openLayerPanel(app)
        app.staticTexts["layerPanel.row.0"].tap()
        app.buttons["toolbar.layersButton"].tap()
        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.r < 80 }),
                        "Selecting the layer underneath re-cuts the sandwich; at rest it is still `composite(full)` and still multiplied")

        // Hiding the cyan layer leaves the magenta one multiplying against nothing, which is itself.
        openLayerPanel(app)
        app.buttons["layerPanel.row.0.visibility"].tap()
        app.buttons["toolbar.layersButton"].tap()
        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.r > 200 && $0.b > 200 }),
                        "With nothing underneath to multiply into, the top layer reads as its own colour again")

        // And undo, which is the same change arriving from the history rather than from a tap.
        // `toggleLayerVisibility` goes through `withStructureUndo`, so the hide above is the newest
        // step and one tap is deterministic — no counting how many of the steps before it were
        // undoable.
        let undo = app.buttons["sideToolbar.undoButton"]
        XCTAssertTrue(undo.waitForExistence(timeout: 5))
        undo.tap()
        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.r < 80 }),
                        "Undoing the hide should bring the multiply back, not leave a composite that still remembers the layer as hidden")
    }

    /// The playhead is the last of §5.2's invalidation triggers, and the one that changes *which*
    /// pixels a layer contributes rather than what they are. The top layer's block is shortened so
    /// that a frame past its end is a frame it does not cover: the canvas has to drop back to the
    /// cyan layer alone there. A sandwich that never rebuilt on a frame change would still be
    /// showing the multiplied composite of frame 1.
    func testMovingThePlayheadRebuildsTheBlendedCanvas() throws {
        let app = XCUIApplication()
        // Order-dependent otherwise: without this, a prior test's on-disk gallery/project state
        // (Projects/Backups/Trash, ProjectBackupManager.swift) can survive into this launch, and
        // this test — unlike its two passing siblings — has been observed to then fail at
        // setBlendMode's row.waitForExistence (BUGS.md). -resetGallery is the same isolation
        // VectorShapeAndRecoveryUITests already uses for its two disk-state-sensitive tests.
        app.launchArguments = ["-resetGallery"]
        XCTAssertTrue(launchIntoEditor(app))
        let canvas = drawCrossedStrokesOnTwoLayers(app)
        setBlendMode(app, layerIndex: 1, to: "multiply")
        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.r < 80 }), "Setup: multiplied at frame 1")

        // Shrink the magenta layer's block. Read the result rather than assuming the drag's reach —
        // XCUITest's synthetic drags undershoot by a timing-dependent amount (see `performDrag`).
        performDrag(app, identifier: "timeline.cel.1.0.rightHandle", totalDelta: -260)
        guard let block = readCel(app, layerIndex: 1, celIndex: 0) else {
            return XCTFail("Could not read the shortened block")
        }
        XCTAssertLessThan(block.length, 12, "Setup: the drag should have shortened the block")

        let ruler = app.otherElements["timeline.ruler"]
        XCTAssertTrue(ruler.waitForExistence(timeout: 5))
        let start = ruler.coordinate(withNormalizedOffset: CGVector(dx: 0.02, dy: 0.5))
        // 30pt per frame, and one frame past the block's end is enough.
        start.press(forDuration: 0.2,
                    thenDragTo: start.withOffset(CGVector(dx: CGFloat(block.start + block.length + 1) * 30, dy: 0)),
                    withVelocity: .slow, thenHoldForDuration: 0.2)
        guard let (current, _) = readFrameLabel(app) else { return XCTFail("Could not read the frame label") }
        XCTAssertGreaterThan(current, block.start + block.length,
                             "Setup: the playhead has to land past the shortened block for this to test anything")

        XCTAssertNotNil(waitForPixel(canvas, at: crossing, matches: { $0.g > 200 && $0.b > 200 && $0.r < 120 }),
                        "Past the magenta block there is nothing to multiply, so the canvas is the cyan layer alone — a stale composite would still read blue")
    }

    // MARK: - §4.3 compositor nodes
    //
    // A node is stored as an ordinary `LayerFolder`, so every one of these would pass trivially
    // against two identical folder rows. What each asserts is the *difference* the panel draws on top
    // of that sameness — the node badge, the operand positions, and the two controls a node does not
    // get.

    /// One tap creates the node, and nothing else: a node arrives empty like a folder and is filled
    /// the same way. The row has to say it is a node, because nothing structural distinguishes it.
    func testAddingMixNodeShowsAnEmptyNodeRow() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addMixNodeFromAddMenu(app)

        XCTAssertTrue(app.staticTexts["layerPanel.folder.Mix 1"].waitForExistence(timeout: 5),
                      "The node row should appear as soon as it's created, with nothing in it")
        XCTAssertEqual(app.otherElements["layerPanel.folder.Mix 1.compositor"].value as? String, "node,normal",
                       "The row has to say it is a node — nothing structural distinguishes it from a folder")
        XCTAssertFalse(app.staticTexts["layerPanel.folder.Input A"].exists,
                       "Input slot folders are gone: a node's operands are whatever the artist drags in")
    }

    /// A node that cannot be filled is decoration. The drop goes through the same restack a folder
    /// drop uses, and the layer becomes **input 0** — the backdrop — because it is the only child.
    func testALayerDropsStraightIntoANodeAndBecomesItsFirstInput() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addMixNodeFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Mix 1"].waitForExistence(timeout: 5))
        XCTAssertEqual(rowFolder(app, layerIndex: 0), "", "Setup: the layer starts outside the node")

        dragRow(layerCell(app, layerIndex: 0), onto: folderCell(app, named: "Mix 1"), dropDY: 0.5)

        XCTAssertEqual(rowFolder(app, layerIndex: 0), "Mix 1",
                       "A node takes a drop like any other folder — that is the whole point of storing it as one")
        XCTAssertEqual(app.otherElements["layerPanel.row.0.compositor"].value as? String, "input,0",
                       "And the row says which operand it is, which the named slot folders used to carry")
    }

    /// The mode is the entire content of a Mix's op, so it is editable and it shows on the row without
    /// opening options (§7's rule, applied to a node). **It is also the node's only dropdown** —
    /// §4.3's second owner decision took the folder's own blend mode away, because a node's output
    /// always lands Normal on whatever is beneath it.
    func testMixNodeModeIsTheNodesOnlyDropdown() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addMixNodeFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Mix 1"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Mix 1.options"].tap()
        let mixPicker = app.buttons["layerOptions.mixModeButton"]
        XCTAssertTrue(mixPicker.waitForExistence(timeout: 5), "A node's options lead with its op")
        XCTAssertEqual(mixPicker.value as? String, "normal", "A fresh Mix starts at Normal")
        XCTAssertFalse(app.buttons["layerOptions.blendModeButton"].exists,
                       "Two dropdowns on one row is the clutter the owner called out, and the second one's job is done by putting the node in a folder")
        XCTAssertFalse(app.switches["layerOptions.passThroughToggle"].exists,
                       "Pass Through is inert on a node — a `.mix` always buffers, so there is no reading of it the op could honour")

        mixPicker.tap()
        let multiply = app.buttons["layerOptions.mixMode.multiply"]
        XCTAssertTrue(multiply.waitForExistence(timeout: 5))
        multiply.tap()

        XCTAssertEqual(mixPicker.value as? String, "multiply")
        XCTAssertEqual(app.otherElements["layerPanel.folder.Mix 1.compositor"].value as? String, "node,multiply",
                       "And the row shows it immediately, the way a layer's blend mode does")

        // Close and reopen to confirm the pick reached `setMixBlendMode` rather than staying local
        // to the control.
        app.buttons["layerOptions.close"].tap()
        app.buttons["layerPanel.folder.Mix 1.options"].tap()
        XCTAssertEqual(app.buttons["layerOptions.mixModeButton"].value as? String, "multiply",
                       "The picker should reflect the node's op, not reset when the panel reopens")
    }

    /// The two controls a node keeps, and one it gained. Rename and Delete are the folder menu's,
    /// unchanged — **Delete is plain "Delete" now**, because deleting a node promotes its children
    /// like any folder (§4.3's first owner decision) rather than taking the subtree with it. The mask
    /// section is the gain: a node's mask clips its folded result, which the slot-era node had nothing
    /// to offer it for.
    func testANodesOptionsKeepRenameDeleteAndTheMaskSection() throws {
        let app = XCUIApplication()
        XCTAssertTrue(launchIntoEditor(app))
        openLayerPanel(app)
        addMixNodeFromAddMenu(app)
        XCTAssertTrue(app.staticTexts["layerPanel.folder.Mix 1"].waitForExistence(timeout: 5))

        app.buttons["layerPanel.folder.Mix 1.options"].tap()
        XCTAssertTrue(app.buttons["layerOptions.rename"].waitForExistence(timeout: 5),
                      "Sanity: the node's options menu opened")
        XCTAssertTrue(app.buttons["layerOptions.deleteFolder"].exists,
                      "A node is deletable like any folder, and the label no longer warns about inputs going with it")
        XCTAssertEqual(app.buttons["layerOptions.deleteFolder"].label, "Delete")
        XCTAssertTrue(app.staticTexts["layerOptions.maskSummary"].exists,
                      "The mask section shows on a node: its mask clips the folded result")
    }
}
